import { createConditionalDepHolder, getQueueToken, } from '@nestjs/bull-shared';
import { flatten } from '@nestjs/common';
import { BULL_CONFIG_DEFAULT_TOKEN, getFlowProducerOptionsToken, getFlowProducerToken, getQueueOptionsToken, getSharedConfigToken, } from './utils/index.js';
import { getConnectionStatus, isAdvancedProcessor, isAdvancedSeparateProcessor, isProcessorCallback, isSeparateProcessor, } from './utils/helpers.js';
function createQueueAndWorkers(options, queueClass, workerClass) {
    const queueName = options.name ?? 'default';
    const queue = options.backendFactory
        ? new queueClass(queueName, options, options.backendFactory)
        : new queueClass(queueName, options);
    let workerRefs = [];
    if (options.processors) {
        workerRefs = options.processors.map((processor) => {
            if (isAdvancedProcessor(processor)) {
                const { callback, backendFactory, ...processorOptions } = processor;
                const targetBackendFactory = backendFactory ?? options.backendFactory;
                const workerOpts = {
                    connection: options.connection,
                    sharedConnection: options.sharedConnection,
                    prefix: options.prefix,
                    telemetry: options.telemetry,
                    ...processorOptions,
                };
                return targetBackendFactory
                    ? new workerClass(queueName, callback, workerOpts, targetBackendFactory)
                    : new workerClass(queueName, callback, workerOpts);
            }
            else if (isAdvancedSeparateProcessor(processor)) {
                const { path, backendFactory, ...processorOptions } = processor;
                const targetBackendFactory = backendFactory ?? options.backendFactory;
                const workerOpts = {
                    connection: options.connection,
                    sharedConnection: options.sharedConnection,
                    prefix: options.prefix,
                    telemetry: options.telemetry,
                    ...processorOptions,
                };
                return targetBackendFactory
                    ? new workerClass(queueName, path, workerOpts, targetBackendFactory)
                    : new workerClass(queueName, path, workerOpts);
            }
            else if (isSeparateProcessor(processor)) {
                const workerOpts = {
                    connection: options.connection,
                    sharedConnection: options.sharedConnection,
                    prefix: options.prefix,
                    telemetry: options.telemetry,
                };
                return options.backendFactory
                    ? new workerClass(queueName, processor, workerOpts, options.backendFactory)
                    : new workerClass(queueName, processor, workerOpts);
            }
            else if (isProcessorCallback(processor)) {
                const workerOpts = {
                    connection: options.connection,
                    sharedConnection: options.sharedConnection,
                    prefix: options.prefix,
                    telemetry: options.telemetry,
                };
                return options.backendFactory
                    ? new workerClass(queueName, processor, workerOpts, options.backendFactory)
                    : new workerClass(queueName, processor, workerOpts);
            }
        });
    }
    queue.onApplicationShutdown =
        async function () {
            const closeWorkers = workerRefs.map((worker) => worker.close());
            await Promise.all(closeWorkers);
            await this.close();
            if (options.forceDisconnectOnShutdown) {
                const status = await getConnectionStatus(this);
                if (status !== 'closed' && this.disconnect) {
                    return this.disconnect();
                }
            }
        };
    return queue;
}
function createFlowProducers(options, flowProducerClass) {
    const flowProducer = options.backendFactory
        ? new flowProducerClass(options, options.backendFactory)
        : new flowProducerClass(options);
    flowProducer.onApplicationShutdown =
        async function () {
            await this.close();
            if (options.forceDisconnectOnShutdown ?? true) {
                const status = await getConnectionStatus(this);
                if (status !== 'closed' && this.disconnect) {
                    return this.disconnect();
                }
            }
        };
    return flowProducer;
}
export function createQueueOptionProviders(options) {
    const providers = options.map((option) => {
        const optionalSharedConfigHolder = createConditionalDepHolder(getSharedConfigToken(option.configKey), BULL_CONFIG_DEFAULT_TOKEN);
        return [
            optionalSharedConfigHolder,
            {
                provide: getQueueOptionsToken(option.name),
                useFactory: (optionalDepHolder) => {
                    return {
                        ...optionalDepHolder.getDependencyRef(option.name),
                        ...option,
                    };
                },
                inject: [optionalSharedConfigHolder],
            },
        ];
    });
    return flatten(providers);
}
export function createFlowProducerOptionProviders(options) {
    const providers = options.map((option) => {
        const optionalSharedConfigHolder = createConditionalDepHolder(getSharedConfigToken(option.configKey), BULL_CONFIG_DEFAULT_TOKEN);
        return [
            optionalSharedConfigHolder,
            {
                provide: getFlowProducerOptionsToken(option.name),
                useFactory: (optionalDepHolder) => {
                    return {
                        ...optionalDepHolder.getDependencyRef(option.name),
                        ...option,
                    };
                },
                inject: [optionalSharedConfigHolder],
            },
        ];
    });
    return flatten(providers);
}
export function createQueueProviders(options, queueClass, workerClass) {
    const queueProviders = options.map((item) => ({
        provide: getQueueToken(item.name),
        useFactory: (queueOptions) => {
            const queueName = queueOptions.name || item.name;
            return createQueueAndWorkers({ ...queueOptions, name: queueName }, queueClass, workerClass);
        },
        inject: [getQueueOptionsToken(item.name)],
    }));
    return queueProviders;
}
export function createFlowProducerProviders(options, flowProducerClass) {
    const flowProducerProviders = options.map((item) => ({
        provide: getFlowProducerToken(item.name),
        useFactory: (flowProducerOptions) => {
            const flowProducerName = flowProducerOptions.name || item.name;
            return createFlowProducers({ ...flowProducerOptions, name: flowProducerName }, flowProducerClass);
        },
        inject: [getFlowProducerOptionsToken(item.name)],
    }));
    return flowProducerProviders;
}
